using System.Collections.Generic;using System.Data.SQLite;using System.Globalization;using System.Linq;using System.Threading;using System.Threading.Tasks;using AlKhayal.Application.Delivery;using Dapper;
namespace AlKhayal.Data.Delivery
{
 public sealed class SqliteDeliveryStore:IDeliveryStore
 { readonly string cs; public SqliteDeliveryStore(string connectionString){cs=connectionString;}
  public async Task<IReadOnlyList<Driver>> DriversAsync(string search,bool activeOnly,CancellationToken ct,int? limit=null,long? id=null){using(var c=new SQLiteConnection(cs)){var like="%"+(search??"").Replace("%","\\%").Replace("_","\\_")+"%";return (await c.QueryAsync<Driver>(new CommandDefinition("SELECT Id,Name,Phone,IsActive FROM Drivers WHERE (@Id IS NULL OR Id=@Id) AND (@Active=0 OR IsActive=1) AND (@Search='' OR Name LIKE @Like ESCAPE '\\' OR Phone LIKE @Like ESCAPE '\\') ORDER BY CASE WHEN Phone=@Search THEN 0 ELSE 1 END,Name,Id LIMIT @Limit",new{Id=id,Limit=limit??-1,Search=search??"",Like=like,Active=activeOnly?1:0},cancellationToken:ct))).ToList();}}
  public async Task<Driver> SaveDriverAsync(Driver d,CancellationToken ct){using(var c=new SQLiteConnection(cs)){await c.OpenAsync(ct).ConfigureAwait(false);var now=System.DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture);if(d.Id<=0){d.Id=await c.ExecuteScalarAsync<long>(new CommandDefinition("INSERT INTO Drivers(Name,Phone,IsActive,CreatedUtc,UpdatedUtc) VALUES(@Name,@Phone,@IsActive,@Now,@Now); SELECT last_insert_rowid();",new{d.Name,d.Phone,d.IsActive,Now=now},cancellationToken:ct)).ConfigureAwait(false);}else if(await c.ExecuteAsync(new CommandDefinition("UPDATE Drivers SET Name=@Name,Phone=@Phone,IsActive=@IsActive,UpdatedUtc=@Now WHERE Id=@Id",new{d.Id,d.Name,d.Phone,d.IsActive,Now=now},cancellationToken:ct)).ConfigureAwait(false)!=1)return null;return d;}}
  public async Task<DeliveryPage> OrdersAsync(string search,string status,long? driverId,int page,int pageSize,CancellationToken ct,long? invoiceId=null){using(var c=new SQLiteConnection(cs)){var term=(search??"").Trim();var like="%"+term.Replace("%","\\%").Replace("_","\\_")+"%";var args=new{InvoiceId=invoiceId,Search=term,Like=like,Status=status??"",DriverId=driverId,Limit=pageSize,Offset=(page-1)*pageSize};const string where=" FROM SalesInvoiceDeliveries d JOIN SalesInvoices si ON si.Id=d.SalesInvoiceId WHERE (@InvoiceId IS NULL OR si.Id=@InvoiceId) AND si.Status='posted' AND NOT EXISTS(SELECT 1 FROM SalesCancellations sc WHERE sc.SalesInvoiceId=si.Id) AND NOT EXISTS(SELECT 1 FROM SalesInvoiceCorrections sic WHERE sic.PreviousInvoiceId=si.Id) AND (@Search='' OR si.InvoiceNumber LIKE @Like ESCAPE '\\' OR d.CustomerName LIKE @Like ESCAPE '\\' OR d.PrimaryPhone LIKE @Like ESCAPE '\\') AND (@Status='' OR d.Status=@Status) AND (@DriverId IS NULL OR d.DriverId=@DriverId)";var total=await c.ExecuteScalarAsync<long>(new CommandDefinition("SELECT COUNT(*)"+where,args,cancellationToken:ct)).ConfigureAwait(false);var items=(await c.QueryAsync<DeliveryOrder>(new CommandDefinition("SELECT d.SalesInvoiceId,si.InvoiceNumber,si.InvoiceDate,d.CustomerName,d.PrimaryPhone,d.Address,d.DriverName,d.Status,d.FeeScaled,si.TotalScaled"+where+" ORDER BY si.Id DESC LIMIT @Limit OFFSET @Offset",args,cancellationToken:ct))).ToList();return new DeliveryPage{Items=items,Total=total,Page=page,PageSize=pageSize};}}
  public async Task SetStatusAsync(long invoiceId,string status,CancellationToken ct){using(var c=new SQLiteConnection(cs)){var n=await c.ExecuteAsync(new CommandDefinition("UPDATE SalesInvoiceDeliveries SET Status=@Status,UpdatedUtc=CASE WHEN Status=@Status THEN UpdatedUtc ELSE @Now END WHERE SalesInvoiceId=@Id AND EXISTS(SELECT 1 FROM SalesInvoices WHERE Id=@Id AND Status='posted' AND NOT EXISTS(SELECT 1 FROM SalesCancellations WHERE SalesInvoiceId=@Id) AND NOT EXISTS(SELECT 1 FROM SalesInvoiceCorrections WHERE PreviousInvoiceId=@Id))",new{Id=invoiceId,Status=status,Now=System.DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture)},cancellationToken:ct)).ConfigureAwait(false);if(n!=1)throw new System.ArgumentException("طلب التوصيل غير موجود أو لم يعد منشورًا.");}}
 }
}
